sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    const DIVIDER_BUTTON_POSITION = "top";

    let dividerButtonIcon, dividerButtonTooltip, dividerButtonLabel;

    if (api.state.isInnerPaneExpanded === true) {
        dividerButtonIcon = "chevron-left-outline";
        dividerButtonTooltip = "Collapse left panel";
        dividerButtonLabel = "Collapse left panel";
    } else {
        dividerButtonIcon = "chevron-right-outline";
        dividerButtonTooltip = "Expand left panel";
        dividerButtonLabel = "Expand left panel";
    }

    return {
        "position": DIVIDER_BUTTON_POSITION,
        "buttonProps": {
            "icon": dividerButtonIcon,
            "tooltip-content": dividerButtonTooltip,
            "config-aria": {
                button: {
                    "aria-label": dividerButtonLabel
                }
            },
        }
    };
}
